package thaumcraft.verification;
import com.google.gson.*;
import com.mojang.blaze3d.vertex.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import thaumcraft.client.*;
import thaumcraft.client.model.TaintacleModel;
import thaumcraft.entities.R5Entities;
/** Actual native dispatcher registrations, original frame pixels and GPU buffers for the new bosses. */
@EventBusSubscriber(modid="thaumcraft_r3_test",value=Dist.CLIENT)
public final class ClientBossChampionVerification {
    private static boolean done;
    @SubscribeEvent public static void tick(ClientTickEvent.Post event)throws Exception{
        if(done||!"boss-champions-client".equals(System.getProperty("thaumcraft.r3.phase")))return;var mc=net.minecraft.client.Minecraft.getInstance();if(!(mc.screen instanceof net.minecraft.client.gui.screens.TitleScreen)||mc.getOverlay()!=null)return;done=true;var root=Path.of(System.getProperty("thaumcraft.r3.root"));var result=new JsonObject();var checks=new ArrayList<String>();
        try{
            ClientBossNameVerification.run(mc,checks);
            var field=net.minecraft.client.renderer.entity.EntityRenderDispatcher.class.getDeclaredField("renderers");field.setAccessible(true);var renderers=(Map<?,?>)field.get(mc.getEntityRenderDispatcher());for(var pair:List.of(Map.entry(R5Entities.CULTIST_LEADER.get(),"CultistRenderer"),Map.entry(R5Entities.CULTIST_PORTAL.get(),"CultistPortalRenderer"),Map.entry(R5Entities.TAINTACLE_GIANT.get(),"GiantTaintacleRenderer")))require(renderers.get(pair.getKey()).getClass().getName().endsWith(pair.getValue()),"native dispatcher "+pair.getValue(),checks);
            for(int ticks:new int[]{0,1,20,49,50,100,199})for(int hurt:new int[]{0,1,5,10})for(int pulse:new int[]{0,1,5,10})for(float health:new float[]{500,250,1}){var shape=CultistPortalRenderer.shape(ticks,hurt,pulse,health,500,.5f,750000000L);require(Float.isFinite(shape.horizontal())&&Float.isFinite(shape.vertical())&&Float.isFinite(shape.alpha())&&shape.frame()==0,"source portal growth/hurt/pulse/health billboard state",checks);}var fresh=CultistPortalRenderer.shape(0,0,0,500,500,0,0);require(fresh.horizontal()==0&&fresh.vertical()==1.5f&&fresh.alpha()==1&&fresh.frame()==15,"source zero-age portal and reversed frame15",checks);
            var model=new TaintacleModel(TaintacleModel.create(10).bakeRoot(),10);var capture=new Capture();model.renderToBuffer(new PoseStack(),capture,220,OverlayTexture.NO_OVERLAY,-1);require(capture.rows.size()==12*24,"giant/common tentacle source12 cuboids",checks);require(capture.rows.stream().allMatch(v->Float.isFinite(v[0])&&Float.isFinite(v[1])&&Float.isFinite(v[2])),"recursive taper remains finite",checks);var pose=new PoseStack();pose.translate(0,0,-100);model.renderToBuffer(pose,mc.renderBuffers().bufferSource().getBuffer(RenderType.entityTranslucent(ResourceLocation.parse("thaumcraft:textures/models/taintacle.png"))),220,OverlayTexture.NO_OVERLAY,-1);mc.renderBuffers().bufferSource().endBatch();require(org.lwjgl.opengl.GL11.glGetError()==0,"native giant tentacle GPU draw",checks);
            var meshClass=Class.forName("thaumcraft.client.OriginalObjMesh");var get=meshClass.getDeclaredMethod("get",String.class);get.setAccessible(true);var mesh=get.invoke(null,"hemis");var draw=meshClass.getDeclaredMethod("renderParticles",PoseStack.class,VertexConsumer.class,int.class,int.class);draw.setAccessible(true);
            for(String name:List.of("RIPPLE","RUNES")){var typeField=ChampionShieldEffects.class.getDeclaredField(name);typeField.setAccessible(true);var type=(net.minecraft.client.particle.ParticleRenderType)typeField.get(null);for(int frame=1;frame<=15;frame++){final int f=frame;var vertices=new Capture();draw.invoke(mesh,new PoseStack(),vertices,frame,220);require(!vertices.rows.isEmpty()&&vertices.rows.stream().allMatch(v->v[4]>=(f-1)/15f-1e-6&&v[4]<=f/15f+1e-6),"original shield hemisphere atlas frame"+name+frame,checks);var builder=type.begin(Tesselator.getInstance(),mc.getTextureManager());var gpuPose=new PoseStack();gpuPose.translate(0,0,-100);draw.invoke(mesh,gpuPose,builder,frame,220);BufferUploader.drawWithShader(builder.buildOrThrow());require(org.lwjgl.opengl.GL11.glGetError()==0,"native shield GPU frame"+name+frame,checks);}}
            for(String atlas:List.of("hemis_frames","sonic_frames")){try(var input=mc.getResourceManager().open(ResourceLocation.parse("thaumcraft:textures/models/"+atlas+".png"));var packed=com.mojang.blaze3d.platform.NativeImage.read(input)){for(int frame=1;frame<=15;frame++){String original=atlas.equals("hemis_frames")?"hemis":"ripple";try(var source=mc.getResourceManager().open(ResourceLocation.parse("thaumcraft:textures/models/"+original+frame+".png"));var image=com.mojang.blaze3d.platform.NativeImage.read(source)){require(packed.getWidth()==image.getWidth()&&packed.getHeight()==image.getHeight()*15,"unchanged source frame dimensions"+atlas+frame,checks);boolean identical=true;for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++)identical&=packed.getPixelRGBA(x,y+(frame-1)*image.getHeight())==image.getPixelRGBA(x,y);require(identical,"byte-exact original frame pixels"+atlas+frame,checks);}}}}
            com.mojang.blaze3d.systems.RenderSystem.depthMask(true);com.mojang.blaze3d.systems.RenderSystem.disableBlend();com.mojang.blaze3d.systems.RenderSystem.defaultBlendFunc();result.addProperty("passed",true);result.addProperty("driver",org.lwjgl.opengl.GL11.glGetString(org.lwjgl.opengl.GL11.GL_RENDERER));
        }catch(Throwable error){result.addProperty("passed",false);result.addProperty("error",error.toString());error.printStackTrace();}
        var hashes=new JsonObject();for(String path:List.of("thaumcraft/client/CultistPortalRenderer.class","thaumcraft/client/GiantTaintacleRenderer.class","thaumcraft/client/ChampionClientEffects.class","thaumcraft/client/ChampionClientEffects$Generic.class","thaumcraft/client/ChampionClientEffects$Breaking.class","thaumcraft/client/ChampionShieldEffects.class","thaumcraft/client/ChampionShieldEffects$Shield.class","thaumcraft/client/ChampionShieldEffects$Shield$1.class","thaumcraft/client/CultistRenderer.class","thaumcraft/client/model/TaintacleModel.class","assets/thaumcraft/textures/models/hemis_frames.png","assets/thaumcraft/textures/models/sonic_frames.png","assets/thaumcraft/textures/misc/cultist_portal.png")){try(var input=ClientBossChampionVerification.class.getClassLoader().getResourceAsStream(path)){if(input==null)throw new IllegalStateException("Missing payload"+path);hashes.addProperty(path,HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(input.readAllBytes())));}}
        result.add("payload_sha256",hashes);result.add("checks",new Gson().toJsonTree(checks));result.addProperty("count",checks.size());result.addProperty("manual_acceptance","pending");result.addProperty("time",java.time.Instant.now().toString());Files.writeString(root.resolve("analysis/full_port/boss-champions-client.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result)+"\n");mc.stop();
    }
    private static void require(boolean condition,String message,List<String> checks){if(!condition)throw new AssertionError(message);checks.add(message);}
    private static final class Capture implements VertexConsumer{final List<float[]> rows=new ArrayList<>();public VertexConsumer addVertex(float x,float y,float z){rows.add(new float[]{x,y,z,0,0});return this;}public VertexConsumer setUv(float u,float v){var row=rows.getLast();row[3]=u;row[4]=v;return this;}public VertexConsumer setColor(int r,int g,int b,int a){return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
    private ClientBossChampionVerification(){}
}
